import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './CSS/AdminDashboard.css';

const API_BASE_URL = 'http://localhost:4000/api/admin';

/* ================================
   SETTINGS SECTION COMPONENT
================================ */
const SettingsView = () => {
  const [settings, setSettings] = useState({
    systemName: 'CoreAdmin Console',
    adminEmail: 'admin@system.com',
    autoBackup: true,
    maintenanceMode: false,
    emailNotifications: true,
    twoFactorAuth: true,
    sessionTimeout: '30'
  });

  const [saveStatus, setSaveStatus] = useState('');

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSettings(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setSaveStatus('Saving...');
    try {
      await axios.put(`${API_BASE_URL}/settings`, settings);
      setSaveStatus('Settings updated successfully!');
      setTimeout(() => setSaveStatus(''), 3000);
    } catch (error) {
      console.error('Failed to update settings:', error);
      setSaveStatus('Failed to save settings.');
    }
  };

  return (
    <div className="split-main-card full-width fade-in">
      <div className="card-header-flex">
        <div>
          <h3>System Settings</h3>
          <p className="card-subtitle">Configure administrative controls, security settings, and global parameters</p>
        </div>
        {saveStatus && (
          <span className="badge-pill tier" style={{ fontWeight: 600 }}>
            {saveStatus}
          </span>
        )}
      </div>

      <form onSubmit={handleSave} style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
        <div>
          <h4 style={{ margin: '0 0 16px 0', fontSize: '0.95rem', color: '#0f172a' }}>General Settings</h4>
          <div className="modal-grid" style={{ gridTemplateColumns: '1fr 1fr' }}>
            <div className="modal-field">
              <label>Console Title</label>
              <input
                type="text"
                name="systemName"
                value={settings.systemName}
                onChange={handleChange}
                className="header-search"
                style={{ width: '100%', borderRadius: '8px', padding: '10px' }}
              />
            </div>
            <div className="modal-field">
              <label>System Administrator Email</label>
              <input
                type="email"
                name="adminEmail"
                value={settings.adminEmail}
                onChange={handleChange}
                style={{ width: '100%', borderRadius: '8px', padding: '10px', border: '1px solid #e2e8f0' }}
              />
            </div>
          </div>
        </div>

        <hr style={{ border: 'none', borderTop: '1px solid #f1f5f9', margin: 0 }} />

        <div>
          <h4 style={{ margin: '0 0 16px 0', fontSize: '0.95rem', color: '#0f172a' }}>Security Controls</h4>
          <div className="modal-grid" style={{ gridTemplateColumns: '1fr 1fr' }}>
            <div className="modal-field">
              <label>Session Timeout (Minutes)</label>
              <select
                name="sessionTimeout"
                value={settings.sessionTimeout}
                onChange={handleChange}
                style={{ width: '100%', borderRadius: '8px', padding: '10px', border: '1px solid #e2e8f0' }}
              >
                <option value="15">15 Minutes</option>
                <option value="30">30 Minutes</option>
                <option value="60">1 Hour</option>
              </select>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginTop: '20px' }}>
              <input
                type="checkbox"
                id="twoFactorAuth"
                name="twoFactorAuth"
                checked={settings.twoFactorAuth}
                onChange={handleChange}
                style={{ width: '18px', height: '18px', cursor: 'pointer' }}
              />
              <label htmlFor="twoFactorAuth" style={{ fontSize: '0.88rem', color: '#0f172a', cursor: 'pointer' }}>
                Enforce Two-Factor Authentication (2FA) for Admins
              </label>
            </div>
          </div>
        </div>

        <hr style={{ border: 'none', borderTop: '1px solid #f1f5f9', margin: 0 }} />

        <div>
          <h4 style={{ margin: '0 0 16px 0', fontSize: '0.95rem', color: '#0f172a' }}>System Operations</h4>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <input
                type="checkbox"
                id="autoBackup"
                name="autoBackup"
                checked={settings.autoBackup}
                onChange={handleChange}
                style={{ width: '18px', height: '18px', cursor: 'pointer' }}
              />
              <label htmlFor="autoBackup" style={{ fontSize: '0.88rem', color: '#0f172a', cursor: 'pointer' }}>
                Enable Automatic Daily Database Backups
              </label>
            </div>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <input
                type="checkbox"
                id="maintenanceMode"
                name="maintenanceMode"
                checked={settings.maintenanceMode}
                onChange={handleChange}
                style={{ width: '18px', height: '18px', cursor: 'pointer' }}
              />
              <label htmlFor="maintenanceMode" style={{ fontSize: '0.88rem', color: '#0f172a', cursor: 'pointer' }}>
                Activate Maintenance Mode (Restrict Non-Admin Access)
              </label>
            </div>
          </div>
        </div>

        <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '12px' }}>
          <button type="submit" className="btn-control-toggle success" style={{ padding: '10px 24px', fontSize: '0.88rem' }}>
            Save Settings
          </button>
        </div>
      </form>
    </div>
  );
};

/* ================================
   MAIN DASHBOARD COMPONENT
================================ */
const AdminDashboard = () => {
  // Navigation & Global States
  const [activeTab, setActiveTab] = useState('overview');
  const [searchQuery, setSearchQuery] = useState('');
  
  // Data States
  const [stats, setStats] = useState({
    totalBuyers: 0,
    totalSellers: 0,
    totalAmount: 0,
    systemStatus: 'Optimal'
  });
  const [users, setUsers] = useState([]);
  const [auditLogs, setAuditLogs] = useState([]);
  
  // UI Interaction States
  const [expandedUserId, setExpandedUserId] = useState(null);
  const [selectedUser, setSelectedUser] = useState(null);
  const [loading, setLoading] = useState(true);

  // Initial Fetch & Real-time Synchronization (5s Polling)
  useEffect(() => {
    fetchDashboardData();
    const interval = setInterval(() => {
      fetchDashboardData();
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  const fetchDashboardData = async () => {
    try {
      const [statsRes, usersRes, logsRes] = await Promise.all([
        axios.get(`${API_BASE_URL}/stats`),
        axios.get(`${API_BASE_URL}/users`),
        axios.get(`${API_BASE_URL}/audit-logs`)
      ]);

      if (statsRes.data) setStats(statsRes.data);
      if (usersRes.data) setUsers(usersRes.data);
      if (logsRes.data) setAuditLogs(logsRes.data);
    } catch (error) {
      console.error('Error fetching dashboard telemetry:', error);
    } finally {
      setLoading(false);
    }
  };

  // Switch Navigation Tabs
  const handleTabChange = (tabName) => {
    setActiveTab(tabName);
    setSelectedUser(null);
  };

  // Toggle User Status (Active / Blocked)
  const handleToggleUserStatus = async (user) => {
    const updatedStatus = user.status === 'Active' ? 'Blocked' : 'Active';
    try {
      await axios.patch(`${API_BASE_URL}/users/${user.id}`, { status: updatedStatus });
      setUsers(prevUsers =>
        prevUsers.map(u => (u.id === user.id ? { ...u, status: updatedStatus } : u))
      );
    } catch (error) {
      console.error('Failed to update user status:', error);
    }
  };

  // Toggle Activity Row Expansion
  const toggleRowExpansion = (userId) => {
    setExpandedUserId(prevId => (prevId === userId ? null : userId));
  };

  // Search Filter
  const filteredUsers = users.filter(user => {
    const query = searchQuery.toLowerCase().trim();
    if (!query) return true;

    const name = user.name ? user.name.toLowerCase() : '';
    const email = user.email ? user.email.toLowerCase() : '';
    const storeName = user.storeName ? user.storeName.toLowerCase() : '';
    const role = user.role ? user.role.toLowerCase() : '';

    return name.includes(query) || email.includes(query) || storeName.includes(query) || role.includes(query);
  });

  const buyersList = filteredUsers.filter(u => u.role === 'User' || !u.role);
  const sellersList = filteredUsers.filter(u => u.role === 'Seller');

  return (
    <div className="admin-wrapper">
      {/* Sidebar Navigation */}
      <aside className="admin-sidebar">
        <div className="sidebar-brand">
          <h2>Core<span>Admin</span></h2>
          <span className="brand-subtitle">Management Console</span>
        </div>
        <nav className="sidebar-nav">
          <button 
            className={activeTab === 'overview' ? 'active' : ''} 
            onClick={() => handleTabChange('overview')}
          >
            Dashboard Overview
          </button>
          <button 
            className={activeTab === 'buyers' ? 'active' : ''} 
            onClick={() => handleTabChange('buyers')}
          >
            Buyer Accounts
          </button>
          <button 
            className={activeTab === 'sellers' ? 'active' : ''} 
            onClick={() => handleTabChange('sellers')}
          >
            Seller Management
          </button>
          {/* ONLY ADDITION TO SIDEBAR */}
          <button 
            className={activeTab === 'settings' ? 'active' : ''} 
            onClick={() => handleTabChange('settings')}
          >
            Settings
          </button>
        </nav>
      </aside>

      {/* Main Content Area */}
      <main className="admin-main">
        {/* Header Bar */}
        <header className="admin-header">
          <div className="header-search">
            <input 
              type="text" 
              placeholder="Search users, sellers, emails..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
          <div className="header-right">
            <a href="/" className="btn-storefront" target="_blank" rel="noreferrer">
              View Storefront
            </a>
            <div className="admin-profile-pill">
              <div className="profile-avatar">SA</div>
              <div className="profile-meta">
                <span className="profile-name">System Admin</span>
                <span className="profile-role">Super Administrator</span>
              </div>
            </div>
          </div>
        </header>

        {/* Dynamic Body Area */}
        <div className="admin-body fade-in">
          {/* KPI Analytics Bar */}
          <div className="kpi-grid">
            <div className="kpi-card kpi-primary hover-lift">
              <div className="kpi-content">
                <div className="kpi-header">
                  <span className="kpi-title text-light-70">Total Platform GMV</span>
                  <span className="kpi-pill-light">Live Sync</span>
                </div>
                <div className="kpi-number text-light">
                  ${stats.totalAmount ? stats.totalAmount.toLocaleString() : '0'}
                </div>
                <div className="kpi-subtext text-light-70">Processed transactions</div>
              </div>
            </div>

            <div className="kpi-card hover-lift">
              <div className="kpi-content">
                <div className="kpi-header">
                  <span className="kpi-title">Active Buyers</span>
                  <span className="kpi-trend positive">+12%</span>
                </div>
                <div className="kpi-number">{stats.totalBuyers || buyersList.length}</div>
                <div className="kpi-subtext">Registered customer base</div>
              </div>
              <div className="kpi-side-bar bg-blue"></div>
            </div>

            <div className="kpi-card hover-lift">
              <div className="kpi-content">
                <div className="kpi-header">
                  <span className="kpi-title">Verified Sellers</span>
                  <span className="kpi-trend positive">+5%</span>
                </div>
                <div className="kpi-number">{stats.totalSellers || sellersList.length}</div>
                <div className="kpi-subtext">Active store merchants</div>
              </div>
              <div className="kpi-side-bar bg-purple"></div>
            </div>

            <div className="kpi-card hover-lift">
              <div className="kpi-content">
                <div className="kpi-header">
                  <span className="kpi-title">System Status</span>
                  <span className="kpi-trend active-status">Online</span>
                </div>
                <div className="kpi-number" style={{ fontSize: '1.4rem' }}>
                  {stats.systemStatus || 'Optimal'}
                </div>
                <div className="kpi-subtext">Server infrastructure</div>
              </div>
              <div className="kpi-side-bar bg-green"></div>
            </div>
          </div>

          {/* Dynamic Tab Views */}
          {loading ? (
            <div style={{ padding: '40px', textAlign: 'center', color: '#64748b' }}>
              Loading platform analytics...
            </div>
          ) : (
            <>
              {/* Overview Tab */}
              {activeTab === 'overview' && (
                <div className="dashboard-split-layout">
                  <div className="split-main-card">
                    <div className="card-header-flex">
                      <div>
                        <h3>Recent Platform Users</h3>
                        <p className="card-subtitle">Overview of recently registered customer profiles</p>
                      </div>
                      <button className="btn-outline-sm" onClick={() => setActiveTab('buyers')}>
                        View All
                      </button>
                    </div>

                    <div className="table-responsive">
                      <table className="enhanced-table">
                        <thead>
                          <tr>
                            <th>User Profile</th>
                            <th>Status</th>
                            <th>Spent</th>
                            <th>Actions</th>
                          </tr>
                        </thead>
                        <tbody>
                          {buyersList.slice(0, 5).map(user => (
                            <React.Fragment key={user.id}>
                              <tr>
                                <td>
                                  <div className="user-cell">
                                    <div className="user-avatar-initial">
                                      {user.name ? user.name.charAt(0).toUpperCase() : 'U'}
                                    </div>
                                    <div>
                                      <span className="user-name">{user.name}</span>
                                      <span className="user-subtext">{user.email}</span>
                                    </div>
                                  </div>
                                </td>
                                <td>
                                  <span className={`badge-pill status-${user.status?.toLowerCase() || 'active'}`}>
                                    <span className="status-indicator-dot"></span>
                                    {user.status || 'Active'}
                                  </span>
                                </td>
                                <td className="text-dark">{user.totalSpent || '$0.00'}</td>
                                <td>
                                  <button 
                                    className="btn-table-action"
                                    onClick={() => toggleRowExpansion(user.id)}
                                  >
                                    {expandedUserId === user.id ? 'Hide Logs' : 'Activity'}
                                  </button>
                                </td>
                              </tr>
                              
                              {expandedUserId === user.id && (
                                <tr className="expanded-activity-row">
                                  <td colSpan="4">
                                    <div className="expanded-activity-panel">
                                      <h4>Audit & Action Timeline for {user.name}</h4>
                                      <ul className="activity-timeline">
                                        {auditLogs
                                          .filter(log => log.entityName === user.name || log.userId === user.id)
                                          .map((log, idx) => (
                                            <li key={idx}>
                                              <span className="activity-timestamp">
                                                {new Date(log.timestamp || Date.now()).toLocaleString()}
                                              </span>
                                              <span className="activity-desc">{log.actionDetail || log.action}</span>
                                            </li>
                                          ))}
                                        {auditLogs.filter(log => log.entityName === user.name || log.userId === user.id).length === 0 && (
                                          <li>
                                            <span className="activity-desc text-secondary">No recent action logs for this user.</span>
                                          </li>
                                        )}
                                      </ul>
                                    </div>
                                  </td>
                                </tr>
                              )}
                            </React.Fragment>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </div>

                  <div className="split-side-card">
                    <div className="card-header-flex">
                      <div>
                        <h3>Top Performing Sellers</h3>
                        <p className="card-subtitle">Active merchant stores</p>
                      </div>
                    </div>
                    <div className="side-vendor-list">
                      {sellersList.slice(0, 4).map(seller => (
                        <div className="vendor-card-item" key={seller.id}>
                          <div className="store-avatar-box">
                            {seller.storeName ? seller.storeName.charAt(0).toUpperCase() : 'S'}
                          </div>
                          <div className="vendor-details">
                            <strong>{seller.storeName || seller.name}</strong>
                            <span className="vendor-meta">{seller.category || 'General Store'}</span>
                            <span className="vendor-revenue">{seller.totalRevenue || '$0.00'}</span>
                          </div>
                          <button 
                            className="btn-outline-sm" 
                            style={{ padding: '4px 8px' }}
                            onClick={() => setSelectedUser(seller)}
                          >
                            Inspect
                          </button>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )}

              {/* Buyers Tab */}
              {activeTab === 'buyers' && (
                <div className="split-main-card full-width">
                  <div className="card-header-flex">
                    <div>
                      <h3>Customer Account Directory</h3>
                      <p className="card-subtitle">Manage customer permissions and view activity stats</p>
                    </div>
                  </div>
                  <div className="table-responsive">
                    <table className="enhanced-table">
                      <thead>
                        <tr>
                          <th>Customer</th>
                          <th>Account Role</th>
                          <th>Tier</th>
                          <th>Status</th>
                          <th className="text-right">Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {buyersList.map(buyer => (
                          <tr key={buyer.id}>
                            <td>
                              <div className="user-cell">
                                <div className="user-avatar-initial">
                                  {buyer.name ? buyer.name.charAt(0).toUpperCase() : 'U'}
                                </div>
                                <div>
                                  <span className="user-name">{buyer.name}</span>
                                  <span className="user-subtext">{buyer.email}</span>
                                </div>
                              </div>
                            </td>
                            <td>
                              <span className="badge-pill role-user">Customer</span>
                            </td>
                            <td>
                              <span className="badge-pill tier">{buyer.tier || 'Standard'}</span>
                            </td>
                            <td>
                              <span className={`badge-pill status-${buyer.status?.toLowerCase() || 'active'}`}>
                                <span className="status-indicator-dot"></span>
                                {buyer.status || 'Active'}
                              </span>
                            </td>
                            <td className="text-right">
                              <button 
                                className="btn-table-action" 
                                style={{ marginRight: '8px' }}
                                onClick={() => setSelectedUser(buyer)}
                              >
                                View Details
                              </button>
                              <button 
                                className={`btn-control-toggle ${buyer.status === 'Blocked' ? 'success' : 'danger'}`}
                                onClick={() => handleToggleUserStatus(buyer)}
                              >
                                {buyer.status === 'Blocked' ? 'Unblock' : 'Block'}
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              {/* Sellers Tab */}
              {activeTab === 'sellers' && (
                <div className="split-main-card full-width">
                  <div className="card-header-flex">
                    <div>
                      <h3>Merchant Store Directory</h3>
                      <p className="card-subtitle">Manage registered vendors, storefronts, and access status</p>
                    </div>
                  </div>
                  <div className="table-responsive">
                    <table className="enhanced-table">
                      <thead>
                        <tr>
                          <th>Store Name / Owner</th>
                          <th>Category</th>
                          <th>Revenue</th>
                          <th>Status</th>
                          <th className="text-right">Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {sellersList.map(seller => (
                          <tr key={seller.id}>
                            <td>
                              <div className="user-cell">
                                <div className="store-avatar-box">
                                  {seller.storeName ? seller.storeName.charAt(0).toUpperCase() : 'S'}
                                </div>
                                <div>
                                  <span className="user-name">{seller.storeName || seller.name}</span>
                                  <span className="user-subtext">Owner: {seller.name} ({seller.email})</span>
                                </div>
                              </div>
                            </td>
                            <td className="text-dark">{seller.category || 'Retail'}</td>
                            <td className="text-dark">{seller.totalRevenue || '$0.00'}</td>
                            <td>
                              <span className={`badge-pill status-${seller.status?.toLowerCase() || 'active'}`}>
                                <span className="status-indicator-dot"></span>
                                {seller.status || 'Active'}
                              </span>
                            </td>
                            <td className="text-right">
                              <button 
                                className="btn-table-action" 
                                style={{ marginRight: '8px' }}
                                onClick={() => setSelectedUser(seller)}
                              >
                                Store Info
                              </button>
                              <button 
                                className={`btn-control-toggle ${seller.status === 'Blocked' ? 'success' : 'danger'}`}
                                onClick={() => handleToggleUserStatus(seller)}
                              >
                                {seller.status === 'Blocked' ? 'Suspend' : 'Activate'}
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}

              {/* ONLY ADDITION TO TAB VIEWS */}
              {activeTab === 'settings' && <SettingsView />}
            </>
          )}
        </div>
      </main>

      {/* Profile/Store Inspection Modal */}
      {selectedUser && (
        <div className="modal-backdrop" onClick={() => setSelectedUser(null)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <div className="modal-header">
              <div>
                <h3>{selectedUser.storeName || selectedUser.name}</h3>
                <span className="modal-subtitle">ID: {selectedUser.id}</span>
              </div>
              <button className="btn-modal-close" onClick={() => setSelectedUser(null)}>&times;</button>
            </div>
            
            <div className="modal-grid">
              <div className="modal-field">
                <label>Account Holder</label>
                <span>{selectedUser.name}</span>
              </div>
              <div className="modal-field">
                <label>Email Address</label>
                <span>{selectedUser.email}</span>
              </div>
              <div className="modal-field">
                <label>Account Role</label>
                <span>{selectedUser.role || 'Customer'}</span>
              </div>
              <div className="modal-field">
                <label>Current Status</label>
                <span>{selectedUser.status || 'Active'}</span>
              </div>
              <div className="modal-field">
                <label>Phone Contact</label>
                <span>{selectedUser.phone || 'N/A'}</span>
              </div>
              <div className="modal-field">
                <label>Location</label>
                <span>{selectedUser.location || 'Not Specified'}</span>
              </div>
              {selectedUser.role === 'Seller' ? (
                <>
                  <div className="modal-field">
                    <label>Store Category</label>
                    <span>{selectedUser.category || 'N/A'}</span>
                  </div>
                  <div className="modal-field">
                    <label>Total Revenue</label>
                    <span>{selectedUser.totalRevenue || '$0.00'}</span>
                  </div>
                </>
              ) : (
                <>
                  <div className="modal-field">
                    <label>Loyalty Tier</label>
                    <span>{selectedUser.tier || 'Standard'}</span>
                  </div>
                  <div className="modal-field">
                    <label>Lifetime Spent</label>
                    <span>{selectedUser.totalSpent || '$0.00'}</span>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
